<section class="card border-0 shadow-sm mb-4"><div class="card-body"><h2 class="h5"><?= \App\Support\I18n::html('Warehouse and near-expiry alerts') ?></h2><form method="post" class="row g-3"><input type="hidden" name="csrf_token" value="<?= $csrf ?>"><input type="hidden" name="version" value="<?= $escape($settings['version']) ?>"><?php if($settings['warehouse_location_id']===null): ?><div class="col-md-6"><label class="form-label" for="warehouse_location_id"><?= \App\Support\I18n::html('Use existing real warehouse (optional)') ?></label><select class="form-select" id="warehouse_location_id" name="warehouse_location_id"><option value=""><?= \App\Support\I18n::html('Create using code below') ?></option><?php foreach($options['warehouses'] as $row): ?><option value="<?= $escape($row['id']) ?>"><?= $escape($row['code']) ?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label" for="warehouse_code"><?= \App\Support\I18n::html('Your real central warehouse code') ?></label><input class="form-control" name="warehouse_code" id="warehouse_code" maxlength="80" value="<?= $escape($field('warehouse_code')) ?>"></div><?php else: ?><p><?= \App\Support\I18n::html('Warehouse') ?> <?= $escape($settings['warehouse_code']) ?> <?= \App\Support\I18n::html('is fixed after configuration; changing it requires a separately reviewed operational procedure.') ?></p><?php endif; ?><div class="col-md-6"><label class="form-label" for="near_expiry_days"><?= \App\Support\I18n::html('Near-expiry calendar days (0–3650)') ?></label><input class="form-control" name="near_expiry_days" id="near_expiry_days" type="number" min="0" max="3650" required value="<?= $escape($field('near_expiry_days',(string)$settings['near_expiry_days'])) ?>"></div><div class="col-12"><button class="btn btn-primary"><?= \App\Support\I18n::html('Save settings') ?></button></div></form></div></section>
<section class="card border-0 shadow-sm"><div class="card-body"><h2 class="h5"><?= \App\Support\I18n::html('Per-product low-stock thresholds') ?></h2><p class="small text-secondary"><?= \App\Support\I18n::html('Alert when available central warehouse stock is at or below the configured threshold. Blank disables the alert; zero is an explicit threshold. No defaults are invented.') ?></p><?php foreach($options['products'] as $row): ?><form method="post" action="<?= $url('/admin/inventory/threshold') ?>" class="row g-2 align-items-end border-bottom pb-3 mb-3"><input type="hidden" name="csrf_token" value="<?= $csrf ?>"><input type="hidden" name="product_id" value="<?= $escape($row['id']) ?>"><input type="hidden" name="version" value="<?= $escape($row['threshold_version']) ?>"><div class="col-sm-7"><label class="form-label" for="threshold-<?= $escape($row['id']) ?>"><?= $escape(\App\Support\I18n::product($row).' / '.$row['sku']) ?></label><input class="form-control" id="threshold-<?= $escape($row['id']) ?>" name="low_stock_threshold" inputmode="numeric" pattern="[0-9]*" maxlength="19" value="<?= $escape($row['low_stock_threshold']) ?>" placeholder="<?= \App\Support\I18n::html('Not configured') ?>"></div><div class="col-sm-5"><button class="btn btn-outline-primary"><?= \App\Support\I18n::html('Save threshold') ?></button></div></form><?php endforeach; ?></div></section>
<?php endif; ?></main><?php require APP_ROOT.'/app/Views/workspace-footer.php'; ?></body></html>
